param([Parameter(Mandatory=$true)][string]$ExpectedSHA256)
$ErrorActionPreference='Stop';$h=Split-Path -Parent $PSCommandPath;$source=Join-Path $h 'candidate.xlsx';$before=Join-Path $h 'before.xlsx';$plan=Get-Content -Raw -Encoding UTF8 -LiteralPath (Join-Path $h 'plan.json')|ConvertFrom-Json
$r=[ordered]@{source=$source;source_sha256=(Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash;before_sha256=(Get-FileHash -LiteralPath $before -Algorithm SHA256).Hash;status='미실행';readonly=$true;saved=$false;blocks=@();rows=@();pink_cells=@();exports=@()}
if($r.source_sha256 -ne $ExpectedSHA256 -or $r.before_sha256 -ne $plan.sha){throw 'Source hash guard mismatch'}
$x=$null;$b=$null;$old=$null;$w=$null;$ow=$null;$oldColors=@{};$preserve=@{};foreach($a in $plan.preserveAddresses){$preserve[$a]=$true}
try{
 $x=New-Object -ComObject Excel.Application;$x.Visible=$false;$x.DisplayAlerts=$false;$x.AskToUpdateLinks=$false;$x.AutomationSecurity=3
 $old=$x.Workbooks.Open($before,0,$true);$ow=$old.Worksheets.Item($plan.sheet);foreach($a in $plan.preserveAddresses){$oldColors[$a]=$ow.Range($a).Interior.Color};$old.Close($false);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($ow);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($old);$ow=$null;$old=$null
 $b=$x.Workbooks.Open($source,0,$true);$w=$b.Worksheets.Item($plan.sheet);$r.native_readonly=[bool]$b.ReadOnly;$r.repair_requested=$false
 $r.original_setup=[ordered]@{zoom=$w.PageSetup.Zoom;fit_wide=$w.PageSetup.FitToPagesWide;fit_tall=$w.PageSetup.FitToPagesTall;orientation=$w.PageSetup.Orientation;repeat_rows=$w.PageSetup.PrintTitleRows}
 $last=[string]$plan.columns[$plan.columns.Length-1]
 foreach($g in $plan.blocks){$parity=if([int]$g.order%2 -eq 1){'FFFFFF'}else{'F5F5F5'};$expect=[Convert]::ToInt32($parity,16);$r.blocks+=[ordered]@{order=$g.order;id=$g.id;start=$g.start;end=$g.end;expected_rgb=$parity;plan_parity_correct=$g.color -eq $parity};for($row=[int]$g.start;$row -le [int]$g.end;$row++){$first=if($preserve.ContainsKey('B'+$row)){'C'}else{'B'};$area=$first+$row+':'+$last+$row;$actual=$w.Range($area).Interior.Color;$r.rows+=[ordered]@{row=$row;order=$g.order;id=$g.id;range=$area;color=$actual;expected_color=$expect;pass=($null -ne $actual -and [int]$actual -eq $expect)}}}
 foreach($a in $plan.preserveAddresses){$color=$w.Range($a).Interior.Color;$r.pink_cells+=[ordered]@{address=$a;before_color=$oldColors[$a];candidate_color=$color;pass=($color -eq $oldColors[$a])}}
 $r.order_sequence_pass=(($plan.blocks.order -join ',') -eq ((1..$plan.blocks.Count) -join ','));$r.plan_parity_pass=@($r.blocks|Where-Object{-not $_.plan_parity_correct}).Count -eq 0;$r.rows_pass=@($r.rows|Where-Object{-not $_.pass}).Count -eq 0;$r.pink_preservation_pass=@($r.pink_cells|Where-Object{-not $_.pass}).Count -eq 0
 $area='B205:'+$last+'211';$w.PageSetup.PrintArea=$area;$pdf=Join-Path $h 'native-order-boundary.pdf';$w.ExportAsFixedFormat(0,$pdf,0,$true,$false);$r.exports+=[ordered]@{name='order-boundary';area=$area;pdf=$pdf;sha256=(Get-FileHash -LiteralPath $pdf -Algorithm SHA256).Hash}
 $r.status=if($r.order_sequence_pass -and $r.plan_parity_pass -and $r.rows_pass -and $r.pink_preservation_pass){'통과'}else{'실패'}
}catch{$r.status='실패';$r.error=$_.Exception.ToString();throw}
finally{if($old){$old.Close($false)};if($b){$b.Close($false)};if($x){$x.Quit()};foreach($o in @($ow,$old,$w,$b,$x)){if($o){[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($o)}};[GC]::Collect();[GC]::WaitForPendingFinalizers();$r.closed_without_saving=$true;$r.source_end_sha256=(Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash;$r.source_unchanged=$r.source_sha256 -eq $r.source_end_sha256;$r.before_end_sha256=(Get-FileHash -LiteralPath $before -Algorithm SHA256).Hash;$r.before_unchanged=$r.before_sha256 -eq $r.before_end_sha256;$r|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $h 'native-check.json') -Encoding utf8}
